int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<pair<int,int>> blueEdges(N - 1), redEdges(N - 1);
    vector<vector<int>> gBlue(N + 1), gRed(N + 1);

    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        blueEdges[i] = {a, b};
        gBlue[a].push_back(b);
        gBlue[b].push_back(a);
    }

    for (int i = 0; i < N - 1; ++i) {
        int c, d;
        cin >> c >> d;
        redEdges[i] = {c, d};
        gRed[c].push_back(d);
        gRed[d].push_back(c);
    }

    // Key fact:
    // The described operation sequence is possible iff the target red graph is also a tree.
    // Reason:
    // - Each operation preserves connectedness and acyclicity of the whole graph after replacing
    //   one edge on a blue path by one red edge between its endpoints.
    // - Conversely, any tree T2 can be obtained from tree T1 by repeatedly taking an edge e in T2
    //   not yet added; in the current blue forest, its endpoints lie in the same blue component,
    //   so there is a blue path between them. Add e and remove any edge on that path. Repeating
    //   this realizes T2.
    //
    // Since the input for target red edges already has N-1 edges, it is achievable iff it is connected.

    vector<int> vis(N + 1, 0);
    queue<int> q;
    q.push(1);
    vis[1] = 1;
    int cnt = 0;

    while (!q.empty()) {
        int v = q.front();
        q.pop();
        ++cnt;
        for (int to : gRed[v]) {
            if (!vis[to]) {
                vis[to] = 1;
                q.push(to);
            }
        }
    }

    cout << (cnt == N ? "YES" : "NO") << '\n';
    return 0;
}

