#define MAXN 200005

typedef struct {
    int to, next;
} Edge;

Edge red[MAXN * 2], blue[MAXN * 2];
int head_red[MAXN], head_blue[MAXN];
int idx_red, idx_blue;

int parent[MAXN][18], depth[MAXN];
int up[MAXN]; // union-find like for blue edges
int used_blue[MAXN]; // mark used blue edges
int deg_red[MAXN];
int queue[MAXN], front, rear;
int n;

void add_edge(int head[], Edge edges[], int *idx, int u, int v) {
    edges[*idx].to = v;
    edges[*idx].next = head[u];
    head[u] = (*idx)++;
}

void dfs_blue(int u, int p) {
    parent[u][0] = p;
    depth[u] = depth[p] + 1;
    for (int i = 1; i < 18; i++)
        parent[u][i] = parent[parent[u][i-1]][i-1];
    for (int i = head_blue[u]; i != -1; i = blue[i].next) {
        int v = blue[i].to;
        if (v == p) continue;
        up[v] = i/2; // edge index
        dfs_blue(v, u);
    }
}

int lca(int u, int v) {
    if (depth[u] < depth[v]) {
        int tmp = u; u = v; v = tmp;
    }
    int diff = depth[u] - depth[v];
    for (int i = 0; i < 18; i++)
        if (diff & (1 << i))
            u = parent[u][i];
    if (u == v) return u;
    for (int i = 17; i >= 0; i--)
        if (parent[u][i] != parent[v][i]) {
            u = parent[u][i];
            v = parent[v][i];
        }
    return parent[u][0];
}

int find_blue_parent(int u, int target_depth) {
    int diff = depth[u] - target_depth;
    for (int i = 0; i < 18; i++)
        if (diff & (1 << i))
            u = parent[u][i];
    return u;
}

int main() {
    scanf("%d", &n);
    memset(head_blue, -1, sizeof(head_blue));
    memset(head_red, -1, sizeof(head_red));
    idx_blue = idx_red = 0;

    for (int i = 0; i < n-1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        add_edge(head_blue, blue, &idx_blue, a, b);
        add_edge(head_blue, blue, &idx_blue, b, a);
    }
    for (int i = 0; i < n-1; i++) {
        int c, d;
        scanf("%d %d", &c, &d);
        add_edge(head_red, red, &idx_red, c, d);
        add_edge(head_red, red, &idx_red, d, c);
        deg_red[c]++; deg_red[d]++;
    }

    depth[0] = -1;
    dfs_blue(1, 0);

    // queue leaves of red tree
    for (int i = 1; i <= n; i++)
        if (deg_red[i] == 1) queue[rear++] = i;

    int ok = 1;
    int matched_edges = 0;
    int used_blue_edge[MAXN] = {0};

    while (front < rear) {
        int u = queue[front++];
        if (deg_red[u] != 1) continue;
        // find its only red neighbor
        int v = -1;
        for (int i = head_red[u]; i != -1; i = red[i].next) {
            int to = red[i].to;
            if (deg_red[to] > 0) {
                v = to;
                break;
            }
        }
        if (v == -1) continue;

        int w = lca(u, v);
        // find a blue edge on path u-v
        int found = 0;
        // try climbing from u
        int x = u;
        while (x != w) {
            int eid = up[x];
            if (!used_blue_edge[eid]) {
                used_blue_edge[eid] = 1;
                found = 1;
                matched_edges++;
                break;
            }
            x = parent[x][0];
        }
        if (!found) {
            x = v;
            while (x != w) {
                int eid = up[x];
                if (!used_blue_edge[eid]) {
                    used_blue_edge[eid] = 1;
                    found = 1;
                    matched_edges++;
                    break;
                }
                x = parent[x][0];
            }
        }
        if (!found) {
            ok = 0;
            break;
        }

        // remove red leaf u
        deg_red[u]--;
        deg_red[v]--;
        if (deg_red[v] == 1) queue[rear++] = v;
    }

    if (matched_edges == n-1 && ok) printf("YES\n");
    else printf("NO\n");

    return 0;
}

