static int cmp_pair(const void *a, const void *b) {
    const Pair *x = (const Pair *)a;
    const Pair *y = (const Pair *)b;
    if (x->u != y->u) return x->u - y->u;
    return x->v - y->v;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Pair *A = (Pair *)malloc((N - 1) * sizeof(Pair));
    Pair *C = (Pair *)malloc((N - 1) * sizeof(Pair));

    for (int i = 0; i < N - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        if (a > b) { int t = a; a = b; b = t; }
        A[i].u = a; A[i].v = b;
    }
    for (int i = 0; i < N - 1; i++) {
        int c, d;
        scanf("%d %d", &c, &d);
        if (c > d) { int t = c; c = d; d = t; }
        C[i].u = c; C[i].v = d;
    }

    qsort(A, N - 1, sizeof(Pair), cmp_pair);
    qsort(C, N - 1, sizeof(Pair), cmp_pair);

    for (int i = 0; i < N - 1; i++) {
        if (A[i].u != C[i].u || A[i].v != C[i].v) {
            puts("NO");
            free(A);
            free(C);
