public class Main {
    static List<Integer>[] g;
    static int[] parent;
    static int[] depth;
    static int[] tin, tout;
    static int timer;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();
        int[][] edges = new int[N - 1][2];
        for (int i = 0; i < N - 1; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            edges[i][0] = a;
            edges[i][1] = b;
            g[a].add(b);
            g[b].add(a);
        }

        int[][] redEdges = new int[N - 1][2];
        for (int i = 0; i < N - 1; i++) {
            redEdges[i][0] = sc.nextInt();
            redEdges[i][1] = sc.nextInt();
        }

        // Build LCA structure
        int LOG = 20;
        parent = new int[N + 1];
        depth = new int[N + 1];
        tin = new int[N + 1];
        tout = new int[N + 1];
        int[][] up = new int[N + 1][LOG];
        dfs(1, 0, up);

        // For each red edge, we need to check if the path in the original tree
        // between its endpoints can be assigned a unique blue edge.
        // This is equivalent to checking if the edges form a matching in the
        // "path-edge incidence" sense — essentially, each blue edge must be used at most once.

        // We'll use a difference array on tree to count how many red paths cover each blue edge.
        int[] diff = new int[N + 1];
        for (int i = 0; i < N - 1; i++) {
            int u = redEdges[i][0];
            int v = redEdges[i][1];
            int l = lca(u, v, up);
            diff[u]++;
            diff[v]++;
            diff[l] -= 2;
        }

        // Propagate differences to get edge usage counts
        int[] edgeCount = new int[N + 1];
        dfsCount(1, 0, diff, edgeCount);

        // Each blue edge should be covered exactly once
        boolean possible = true;
        for (int i = 0; i < N - 1; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            if (depth[a] < depth[b]) {
                int tmp = a; a = b; b = tmp;
            }
            // a is deeper
            if (edgeCount[a] != 1) {
                possible = false;
                break;
            }
        }

        System.out.println(possible ? "YES" : "NO");
    }

    static void dfs(int u, int p, int[][] up) {
        tin[u] = timer++;
        parent[u] = p;
        depth[u] = depth[p] + 1;
        up[u][0] = p;
        for (int j = 1; j < up[0].length; j++) {
            up[u][j] = up[up[u][j - 1]][j - 1];
        }
        for (int v : g[u]) {
            if (v != p) {
                dfs(v, u, up);
            }
        }
        tout[u] = timer++;
    }

    static int lca(int u, int v, int[][] up) {
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        int diff = depth[u] - depth[v];
        for (int j = 0; j < up[0].length; j++) {
            if ((diff & (1 << j)) != 0) {
                u = up[u][j];
            }
        }
        if (u == v) return u;
        for (int j = up[0].length - 1; j >= 0; j--) {
            if (up[u][j] != up[v][j]) {
                u = up[u][j];
                v = up[v][j];
            }
        }
        return parent[u];
    }

    static void dfsCount(int u, int p, int[] diff, int[] edgeCount) {
        int sum = diff[u];
        for (int v : g[u]) {
            if (v != p) {
                dfsCount(v, u, diff, edgeCount);
                sum += edgeCount[v];
            }
        }
        edgeCount[u] = sum;
    }
}

