import java.util.*;

public class Main {
    // DSU for Kruskal
    static class DSU {
        int[] p, r;
        DSU(int n) {
            p = new int[n + 1];
            r = new int[n + 1];
            for (int i = 1; i <= n; i++) p[i] = i;
        }
        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }
        boolean union(int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return false;
            if (r[a] < r[b]) {
                int t = a; a = b; b = t;
            }
            p[b] = a;
            if (r[a] == r[b]) r[a]++;
            return true;
        }
    }

    static class Edge {
        int to, id;
        Edge(int to, int id) {
            this.to = to;
            this.id = id;
        }
    }

    static int N;
    static int[] A, B, C, D;

    static ArrayList<Edge>[] g;      // original blue tree
    static ArrayList<Integer>[] red; // target red tree

    static int LOG;
    static int[][] up;
    static int[] depth;
    static int[] parentEdge;

    static int[] cnt;
    static boolean[] usedBlue;

    static void dfsLca(int v, int p) {
        up[0][v] = p;
        for (int k = 1; k < LOG; k++) {
            up[k][v] = up[k - 1][ up[k - 1][v] ];
        }
        for (Edge e : g[v]) {
            if (e.to == p) continue;
            depth[e.to] = depth[v] + 1;
            parentEdge[e.to] = e.id;
            dfsLca(e.to, v);
        }
    }

    static int lca(int a, int b) {
        if (depth[a] < depth[b]) {
            int t = a; a = b; b = t;
        }
        int diff = depth[a] - depth[b];
        for (int k = 0; k < LOG; k++) {
            if (((diff >> k) & 1) != 0) a = up[k][a];
        }
        if (a == b) return a;
        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][a] != up[k][b]) {
                a = up[k][a];
                b = up[k][b];
            }
        }
        return up[0][a];
    }

    static void dfsAcc(int v, int p) {
        for (Edge e : g[v]) {
            if (e.to == p) continue;
            dfsAcc(e.to, v);
            cnt[v] += cnt[e.to];
            if (cnt[e.to] == 1) {
                usedBlue[e.id] = true;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();

        A = new int[N];
        B = new int[N];
        g = new ArrayList[N + 1];
        red = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            g[i] = new ArrayList<>();
            red[i] = new ArrayList<>();
        }

        for (int i = 1; i <= N - 1; i++) {
            A[i] = fs.nextInt();
            B[i] = fs.nextInt();
            g[A[i]].add(new Edge(B[i], i));
            g[B[i]].add(new Edge(A[i], i));
        }

        C = new int[N];
        D = new int[N];
        DSU dsu = new DSU(N);
        boolean ok = true;
        for (int i = 1; i <= N - 1; i++) {
            C[i] = fs.nextInt();
            D[i] = fs.nextInt();
            red[C[i]].add(D[i]);
            red[D[i]].add(C[i]);
            if (!dsu.union(C[i], D[i])) ok = false; // target must be a tree
        }

        if (!ok) {
            System.out.println("NO");
            return;
        }

        LOG = 1;
        while ((1 << LOG) <= N) LOG++;
        up = new int[LOG][N + 1];
        depth = new int[N + 1];
        parentEdge = new int[N + 1];

        dfsLca(1, 1);

        cnt = new int[N + 1];
        for (int i = 1; i <= N - 1; i++) {
            int u = C[i], v = D[i];
            int w = lca(u, v);
            cnt[u]++;
            cnt[v]++;
            cnt[w] -= 2;
        }

        usedBlue = new boolean[N];
        dfsAcc(1, 1);

        int usedCount = 0;
        for (int i = 1; i <= N - 1; i++) if (usedBlue[i]) usedCount++;

        // Necessary and sufficient: every original edge is used by exactly one target edge path.
        // Since there are N-1 target edges and each used edge contributes at least 1,
        // "all edges used" implies each exactly once.
        if (usedCount == N - 1) System.out.println("YES");
        else System.out.println("NO");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

